// Generated by build_flux_ui.py — syncs Sonos zone swipes to input_select + popup artwork.
(function () {
  const SELECT_SCRIPT = 'flux_ui_select_media_zone';
  let lastZone = null;
  let debounce = null;

  function hass() {
    return document.querySelector('home-assistant')?.hass;
  }

  function activeZoneTitle() {
    const dots = document.querySelectorAll('.media-player-dot');
    const slides = document.querySelectorAll('.media-player-track ha-card.media-player');
    if (dots.length && slides.length) {
      const idx = [...dots].findIndex((d) => d.classList.contains('active'));
      if (idx >= 0 && slides[idx]) {
        return slides[idx].querySelector('.media-player-title')?.textContent?.trim() || null;
      }
    }
    const single = document.querySelector('ha-card.media-player .media-player-title');
    return single?.textContent?.trim() || null;
  }

  function syncZone() {
    const zone = activeZoneTitle();
    if (!zone || zone === lastZone) return;
    const h = hass();
    if (!h) return;
    lastZone = zone;
    h.callService('script', SELECT_SCRIPT, { zone });
  }

  function scheduleSync() {
    if (debounce) clearTimeout(debounce);
    debounce = setTimeout(syncZone, 80);
  }

  function observe() {
    const root = document.querySelector('home-assistant');
    if (!root) return;
    new MutationObserver(scheduleSync).observe(root, {
      subtree: true,
      attributes: true,
      attributeFilter: ['class', 'style'],
      childList: true,
    });
    setInterval(syncZone, 600);
    scheduleSync();
  }

  window.addEventListener('load', observe);
  setTimeout(observe, 1500);
})();
